export const CORRECTIONS = {"swine-clinic--swine-asf--detect-การตรวจหาสุกรติดเชื้อ-asfv":[{"severity":"narrows","lectureSays":"โน้ตเขียนว่า antibody detection ถูกขีดห้ามไว้ ไม่ใช้ตรวจหาสุกรติดเชื้อ ASFV","evidenceSays":"WOAH Terrestrial Manual 2024 บทที่ 3.9.1 African swine fever เห็นตรงกันเฉพาะกรณีเชื้อรุนแรง คือมักตรวจไม่พบ antibody ในสุกรที่ติด ASFV สายพันธุ์รุนแรงเพราะตายก่อนสร้าง แต่ระบุด้วยว่าสุกรที่รอดสร้าง antibody ตั้งแต่ 7-10 วันหลังติดเชื้อและคงอยู่นาน ในพื้นที่ที่โรคเป็น endemic หรือเมื่อ outbreak เกิดจากสายพันธุ์ความรุนแรงต่ำถึงปานกลาง การสอบสวนควรรวมการตรวจ antibody ด้วย และ antibody เป็นตัวบ่งชี้ที่ดีของรูปแบบ subacute กับ chronic","examAdvice":"ในข้อสอบให้ตอบตามสไลด์ว่าใช้อาการร่วมกับ PCR และไม่ใช้ antibody detection แต่เวลาเฝ้าระวังในพื้นที่ที่โรคอยู่ประจำถิ่นจริงให้ตรวจ antibody ควบคู่ เพราะ antibody คงอยู่นานในสุกรที่รอดจากสายพันธุ์ไม่รุนแรง","sourceRef":"WOAH Terrestrial Manual 2024, Chapter 3.9.1 African swine fever (infection with African swine fever virus)"}],"swine-clinic--swine-greasypig--greasy-pig-การรักษา-และการควบคุม":[{"severity":"contradicts","lectureSays":"โน้ตเขียนตามสไลด์ว่าให้อาบสุกรป่วยด้วยยาฆ่าเชื้อ เช่น 5% chlorhexidine, 1% Virkon","evidenceSays":"MSD Veterinary Manual หัวข้อ Exudative Epidermitis in Pigs (ปรับปรุง Jan 2026) ให้พ่น antiseptic ทั่วตัวทุกวัน เช่น chlorhexidine solution 0.05% หรือ povidone-iodine 10% ที่เจือจาง 1:50 ซึ่งเจือจางกว่าตัวเลขในโน้ต 100 เท่า ความเข้มข้น 0.05% เป็นระดับเดียวกับที่ใช้ล้างแผลในสัตว์ งาน Effects of four preparations of 0.05% chlorhexidine diacetate on wound healing in dogs, PMID 1626379, doi 10.1111/j.1532-950x.1992.tb00025.x พบว่า chlorhexidine diacetate 0.05% ทุกสูตรฆ่า Staphylococcus intermedius ได้ 100% โดย wound contraction และ epithelialization ไม่ต่างจากกลุ่มควบคุม สไลด์ไม่ได้บอกว่า 5% เป็นความเข้มข้นก่อนหรือหลังเจือจาง","examAdvice":"ในข้อสอบให้ตอบ 5% chlorhexidine หรือ 1% Virkon ตามสไลด์ แต่เวลาใช้จริงให้เจือจาง chlorhexidine เป็น 0.05% ก่อนพ่นหรืออาบ อย่าใช้ความเข้มข้น 5% กับผิวลูกสุกรที่ถลอก","sourceRef":"MSD Veterinary Manual, Exudative Epidermitis in Pigs (last updated Jan 2026) และ PMID 1626379 (doi 10.1111/j.1532-950x.1992.tb00025.x)"},{"severity":"narrows","lectureSays":"โน้ตเขียนว่ายาแรกคือ penicillin หรือ lincomycin และทางเลือกคือ ceftiofur หรือ enrofloxacin","evidenceSays":"งาน An investigation of exudative epidermitis (greasy pig disease) and antimicrobial resistance patterns of Staphylococcus hyicus and Staphylococcus aureus isolated from clinical cases, PMID 23904636 (30 ฝูงใน Ontario) พบ S. hyicus ดื้อ penicillin G และ ampicillin 97% และในกลุ่มนี้ดื้อ ceftiofur 71% งาน Insights into the Virulence and Antimicrobial Resistance of Staphylococcus hyicus Isolates from Spanish Swine Farms, PMID 39335044, doi 10.3390/antibiotics13090871 (49 isolates) พบดื้อ lincosamides 83.7% และ penicillins 75.5% ส่วนงาน Trends in antimicrobial susceptibility in relation to antimicrobial usage and presence of resistance genes in Staphylococcus hyicus isolated from exudative epidermitis in pigs, PMID 12223165, doi 10.1016/s0378-1135(02)00177-3 (467 isolates ใน Denmark ปี 1996-2001) พบดื้อ penicillin 54-75% MSD Veterinary Manual หัวข้อ Exudative Epidermitis in Pigs (ปรับปรุง Jan 2026) ระบุว่ามีรายงานการดื้อยา โดยเฉพาะกลุ่ม beta-lactam และให้เลือกยาตามผล culture กับ susceptibility testing","examAdvice":"ในข้อสอบให้ตอบ penicillin หรือ lincomycin เป็นยาแรกตามสไลด์ แต่เวลารักษาจริงให้ส่งเพาะเชื้อและทำ susceptibility test ก่อนเลือกยา เพราะ S. hyicus ดื้อ penicillin ได้เกินครึ่งของ isolates","sourceRef":"PMID 23904636 และ PMID 39335044 (doi 10.3390/antibiotics13090871)"}],"swine-clinic--swine-ileitis-bacti--brachyspira-swine-dysentery-และ-colonic-spirochetosis":[{"severity":"contradicts","lectureSays":"โน้ตเขียนว่ารอยโรคของ B. pilosicoli พบใน colon และลำไส้เล็ก","evidenceSays":"MSD Veterinary Manual หัวข้อ Intestinal Spirochetosis in Pigs (ปรับปรุง Jul 2026) ระบุว่าโรคนี้จำกัดอยู่ที่ large intestine รอยโรคเบากว่า swine dysentery เยื่อเมือกหนาตัว บางตัวมี catarrhal colitis ร่วมกับ colonic lymph node โต งาน Extensive intestinal spirochaetosis in pigs challenged with Brachyspira pilosicoli, PMID 15017287, doi 10.1099/jmm.0.05403-0 ให้เชื้อแก่สุกรอายุ 6 สัปดาห์ 6 ตัว พบ diffuse catarrhal colitis ทุกตัว และพบเชื้อเกาะแบบ end-on บนผิวเยื่อเมือกของ large intestine ซึ่งตรงกับชื่อ colonic spirochetosis ที่โน้ตใช้เอง","examAdvice":"ในข้อสอบให้ตอบ colon และลำไส้เล็กตามสไลด์ แต่เวลาผ่าซากจริงให้หารอยโรคของ Brachyspira ทั้งสองชนิดที่ลำไส้ใหญ่ ถ้ารอยโรคอยู่ที่ลำไส้เล็กให้นึกถึง Lawsonia หรือ Salmonella ก่อน","sourceRef":"MSD Veterinary Manual, Intestinal Spirochetosis in Pigs (last updated Jul 2026) และ PMID 15017287 (doi 10.1099/jmm.0.05403-0)"}],"swine-clinic--swine-ileitis-bacti--campylobacter-species":[{"severity":"narrows","lectureSays":"โน้ตเขียนว่า C. jejuni พบในสุกรมากกว่า 5% และสัมพันธ์กับอาการในสุกร","evidenceSays":"MSD Veterinary Manual หัวข้อ Enteric Campylobacteriosis in Animals (ปรับปรุง Aug 2026) ระบุว่าสุกรมักเป็นพาหะของ C. coli และบางครั้งชนิดอื่น และงานวิจัยปัจจุบันชี้ว่า Campylobacter spp. ไม่ก่อโรคทางคลินิกในสุกร แม้ตารางในหัวข้อเดียวกันยังลง C. coli ว่าก่อ enteritis ในสุกร หลักฐานจึงไม่ได้ไปทางเดียวกันทั้งหมด แต่ไม่มีส่วนใดที่ผูก C. jejuni กับอาการในสุกร งาน Consequences of Campylobacter jejuni and Campylobacter coli Colonisation of Piglets on Gut Microbiota and Microbial Metabolites, PMID 42197332, doi 10.3390/microorganisms14050945 (ลูกสุกรหย่านม 32 ตัว แบ่งเป็นกลุ่มควบคุมกับกลุ่มที่ให้เชื้อทั้งสองชนิด ติดตาม 4 สัปดาห์) พบว่าเชื้อทั้งสองเกาะที่ jejunum และ caecum ได้ แต่สุกรทุกตัวไม่แสดงอาการ","examAdvice":"ในข้อสอบให้ตอบตามสไลด์ว่า C. jejuni สัมพันธ์กับอาการในสุกร แต่เวลาเจอสุกรท้องเสียจริงอย่าสรุปว่าเกิดจาก Campylobacter เพียงเพราะเพาะเชื้อได้ ให้หาสาเหตุอื่นก่อน และให้น้ำหนักกับเชื้อนี้ในแง่ zoonosis","sourceRef":"MSD Veterinary Manual, Enteric Campylobacteriosis in Animals (last updated Aug 2026) และ PMID 42197332 (doi 10.3390/microorganisms14050945)"}],"swine-clinic--swine-ileitis-bacti--clostridial-enteritis-ในลูกสุกรแรกเกิด":[{"severity":"contradicts","lectureSays":"โน้ตเขียนว่า Clostridium difficile ในลูกสุกรแรกเกิดไม่ท้องเสีย มี necrotizing colitis เล็กน้อย","evidenceSays":"MSD Veterinary Manual หัวข้อ Clostridioides difficile Colitis in Pigs (ปรับปรุง Jul 2026) ระบุว่าลูกสุกรที่ติดเชื้อมักท้องเสียตั้งแต่แรกเกิด พบบ่อยที่อายุ 1-7 วัน และสรุปว่าเชื้อนี้เป็นสาเหตุของท้องเสียระดับเล็กน้อยถึงปานกลางในสัปดาห์แรกของชีวิต บทความทบทวน Clostridial diarrheas in piglets: A review, PMID 36870204, doi 10.1016/j.vetmic.2023.109691 ก็จัด C. perfringens type C และ C. difficile เป็นสาเหตุหลักของ neonatal diarrhea ในสุกรทั้งคู่ ส่วนการบวมน้ำของ colon ที่โน้ตบรรยายตรงกับแหล่งอ้างอิง ซึ่งให้ mesocolonic edema เป็นรอยโรคที่พบบ่อยที่สุด","examAdvice":"ในข้อสอบให้ตอบว่าไม่ท้องเสียตามสไลด์ แต่เวลาเจอลูกสุกรอายุไม่ถึงสัปดาห์ท้องเสียจริง ให้เก็บ C. difficile ไว้ใน differential และส่งตรวจ toxin A/B","sourceRef":"MSD Veterinary Manual, Clostridioides difficile Colitis in Pigs (last updated Jul 2026) และ PMID 36870204 (doi 10.1016/j.vetmic.2023.109691)"},{"severity":"narrows","lectureSays":"ตารางในโน้ตแบ่ง C. perfringens เป็น 5 toxigenic types และให้ major toxin ของ type E เป็น α อย่างเดียว","evidenceSays":"งาน Expansion of the Clostridium perfringens toxin-based typing scheme, PMID 29866424, doi 10.1016/j.anaerobe.2018.04.011 อธิบายว่าระบบ 5 types (A ถึง E) ใช้ typing toxin 4 ตัว คือ α, β, ε และ ι โดย type E คือสายพันธุ์ที่สร้าง α-toxin ร่วมกับ ι-toxin ไม่ใช่ α อย่างเดียว และตั้งแต่ปี 2018 ระบบนี้ขยายเป็น 7 types โดยเพิ่ม type F ที่สร้าง enterotoxin (CPE) และ type G ที่สร้าง NetB ซึ่งก่อ necrotic enteritis ในไก่","examAdvice":"ในข้อสอบให้ตอบ 5 types ตามตารางในสไลด์ แต่จำเพิ่มว่า type E ต้องมี ι-toxin ด้วย และถ้าโจทย์อ้างระบบหลังปี 2018 ให้ตอบ 7 types คือ A ถึง G","sourceRef":"PMID 29866424 (doi 10.1016/j.anaerobe.2018.04.011)"}],"swine-clinic--swine-ileitis-bacti--coccidiosis-balantidiasis-yeast-infection-และ-gastric-ulcer":[{"severity":"contradicts","lectureSays":"โน้ตเขียนตามภาพวงจรชีวิตว่า oocyst ของ Isospora suis sporulate ใน 4-6 วัน","evidenceSays":"งาน Sporogony of Isospora suis Biester, 1934 of swine, PMID 7131190 พบว่า sporulation เสร็จภายใน 56 ชม. ที่ 20 °C, 40 ชม. ที่ 25 °C, 16 ชม. ที่ 30 °C และ 12 ชม. ที่ 37 °C งาน The sporulation time of Isospora suis oocysts from different sources, PMID 3788016, doi 10.1016/0304-4017(86)90002-6 บ่มที่ 25 °C แล้วสรุปว่าใช้เวลาไม่เกิน 48 ชม. ตัวเลขราว 5 วันในวรรณกรรมเป็น prepatent period งาน Endogenous development of the swine coccidium, Isospora suis Biester 1934, PMID 7463245 ให้ prepatent period 5 วัน และ patent period 5-8 วัน","examAdvice":"ในข้อสอบให้ตอบ 4-6 วันตามภาพในสไลด์ แต่เวลาวางแผนล้างคอกคลอดจริงให้จำว่า oocyst พร้อมติดเชื้อได้ภายในไม่ถึง 2 วันในคอกที่อุ่น","sourceRef":"PMID 7131190 และ PMID 3788016 (doi 10.1016/0304-4017(86)90002-6)"}],"swine-clinic--swine-ileitis-bacti--colibacillosis-enterotoxigenic-e-coli-และ-edema-disease":[{"severity":"contradicts","lectureSays":"ตารางในโน้ตให้สายพันธุ์ของ postweaning E. coli diarrhea เป็น K88, K99 และ 987P","evidenceSays":"บทความทบทวน Swine enteric colibacillosis: diagnosis, therapy and antimicrobial resistance, PMID 28794894, doi 10.1186/s40813-017-0063-4 แยกไว้ว่า ETEC ของ neonatal colibacillosis ส่วนใหญ่มี fimbriae F4 (K88), F5 (K99), F6 (987P) หรือ F41 ส่วน ETEC ของ post-weaning diarrhoea มี F4 (K88) และ F18 บทความทบทวน Escherichia coli in postweaning diarrhea in pigs: an update on bacterial types, pathogenesis, and prevention strategies, PMID 16164007, doi 10.1079/ahr2005105 และ MSD Veterinary Manual หัวข้อ Enteric Colibacillosis in Pigs (ปรับปรุง Jul 2026) ให้ตรงกันว่าหลังหย่านมเป็น F4 หรือ F18 ดังนั้น K99 กับ 987P เป็นของลูกสุกรดูดนม และ F18 ไม่ได้จำกัดอยู่ที่ edema disease","examAdvice":"ในข้อสอบให้ตอบ K88, K99, 987P ตามตารางในสไลด์ แต่เวลาแปลผล PCR หรือเลือกวัคซีนจริงให้จำว่าท้องเสียหลังหย่านมเป็น F4 (K88) กับ F18 ส่วน K99 และ 987P เป็นของลูกสุกรแรกเกิด","sourceRef":"PMID 28794894 (doi 10.1186/s40813-017-0063-4) และ PMID 16164007 (doi 10.1079/ahr2005105)"},{"severity":"narrows","lectureSays":"ตารางในโน้ตให้ edema disease เกิด 10-20 วันหลังหย่านม และ postweaning E. coli diarrhea เกิด 4-10 วันหลังหย่านม","evidenceSays":"MSD Veterinary Manual หัวข้อ Edema Disease in Pigs (ปรับปรุง Sept 2024) ให้ edema disease มักเกิด 1-2 สัปดาห์หลังหย่านม และเกิดพร้อม postweaning diarrhea ใน outbreak เดียวกันได้ บทความทบทวน Edema disease, PMID 10707419, doi 10.1016/s0749-0720(15)30142-0 ก็จัดโรคนี้เป็นสาเหตุการป่วยและตายในช่วง 2 สัปดาห์แรกหลังหย่านม ช่วงเวลาของสองโรคจึงซ้อนกัน และ edema disease เริ่มได้ก่อนวันที่ 10","examAdvice":"ในข้อสอบให้ตอบ 10-20 วันและ 4-10 วันหลังหย่านมตามตารางในสไลด์ แต่เวลาเจอเคสจริงอย่าตัด edema disease ออกเพียงเพราะสุกรหย่านมมาไม่ถึง 10 วัน","sourceRef":"MSD Veterinary Manual, Edema Disease in Pigs (last updated Sept 2024) และ PMID 10707419 (doi 10.1016/s0749-0720(15)30142-0)"},{"severity":"narrows","lectureSays":"โน้ตเขียนว่า edema disease เกิดจาก neurotoxin (verotoxin) และอาการชักมาจาก neurotoxin","evidenceSays":"toxin ตัวนี้คือ Shiga toxin 2e (Stx2e หรือ verotoxin 2e) ซึ่งออกฤทธิ์ที่หลอดเลือด ไม่ได้ออกฤทธิ์ที่เซลล์ประสาทโดยตรง บทความทบทวน Edema disease, PMID 10707419, doi 10.1016/s0749-0720(15)30142-0 ระบุว่า Stx2e ทำให้ endothelial cell และ smooth muscle cell ของ small artery กับ arteriole ตาย และ vascular damage ที่ brain stem จนเกิด infarction กับ malacia เป็นสาเหตุหลักของการตาย MSD Veterinary Manual หัวข้อ Edema Disease in Pigs (ปรับปรุง Sept 2024) อธิบายตรงกันว่าเป็น cytotoxin ที่ยับยั้ง protein synthesis และมีเป้าหมายที่ vascular endothelium ทำให้บวมน้ำ เลือดออก และ microthrombosis","examAdvice":"ในข้อสอบให้ตอบ verotoxin ตามสไลด์ แต่ถ้าต้องอธิบายกลไก ให้เขียนว่า Stx2e ทำลายหลอดเลือด อาการทางประสาทเป็นผลจากหลอดเลือดในสมองเสียหาย","sourceRef":"PMID 10707419 (doi 10.1016/s0749-0720(15)30142-0)"}],"swine-clinic--swine-ileitis-bacti--mastitis-metritis-agalactia-syndrome-mma":[{"severity":"narrows","lectureSays":"โน้ตเขียนว่า MMA เกิดจากแบคทีเรีย คือ E. coli, Klebsiella, Enterobacter, Staphylococci และ Streptococci โดย endotoxin รบกวน prolactin และ oxytocin","evidenceSays":"การแยกเชื้อเหล่านี้ได้ยังบอกไม่ได้ว่าแม่สุกรป่วย งาน The role of bacterial pathogens in coliform mastitis in sows, PMID 23540195 เพาะเชื้อจากน้ำนมแม่ป่วย 1,026 ตัวอย่าง เทียบกับแม่ปกติ 972 ตัวอย่างใน 6 ฟาร์ม พบชนิดเชื้อไม่ต่างกันอย่างมีนัยสำคัญ โดยพบ E. coli 70.4% ในแม่ป่วย และ 78.0% ในแม่ปกติ งาน Bacteria in milk from anterior and posterior mammary glands in sows affected and unaffected by postpartum dysgalactia syndrome (PPDS), PMID 19545415, doi 10.1186/1751-0147-51-26 (แม่สุกร 56 ตัว) ได้ผลแบบเดียวกัน MSD Veterinary Manual หัวข้อ Postpartum Dysgalactia Syndrome in Sows (ปรับปรุง Aug 2026) เรียกโรคนี้ว่า multifactorial syndrome ที่ไม่มี etiological diagnosis แน่ชัด โดย endotoxemia เป็นหนึ่งในสามปัจจัยเสี่ยงที่ตั้งสมมติฐานไว้ ร่วมกับ stress และแม่อ้วนที่ไม่กินอาหารหลังคลอด","examAdvice":"ในข้อสอบให้ตอบรายชื่อแบคทีเรียและ endotoxin ตามสไลด์ แต่เวลาเจอฝูงที่มีปัญหาจริงอย่าสรุปจากผลเพาะเชื้อน้ำนมอย่างเดียว ให้แก้ปัจจัยเสี่ยงด้านอาหาร ความเครียด และสุขอนามัยไปพร้อมกัน","sourceRef":"PMID 23540195 และ PMID 19545415 (doi 10.1186/1751-0147-51-26)"}],"swine-clinic--swine-ileitis-bacti--proliferative-enteropathy-ileitis-ชื่อ-รูปแบบ-สาเหตุ-และพยาธิกำเ":[{"severity":"contradicts","lectureSays":"โน้ตเขียนว่า Lawsonia intracellularis เพาะเลี้ยงได้สำเร็จปี 1995","evidenceSays":"งาน Intracellular bacteria of porcine proliferative enteropathy: cultivation and maintenance in vitro, PMID 8501214, doi 10.1128/jcm.31.5.1136-1142.1993 ตีพิมพ์ปี 1993 รายงานการแยกเชื้อจากลำไส้สุกรป่วยครบทั้ง 10 เคส เลี้ยงใน rat enterocyte cell line (IEC-18) และต่อเชื้อได้เกิน 20 passage ส่วนปี 1995 เป็นปีที่เชื้อได้ชื่อ Lawsonia intracellularis และพิสูจน์ Koch's postulates ในงาน Characterization of Lawsonia intracellularis gen. nov., sp. nov., the obligately intracellular bacterium of porcine proliferative enteropathy, PMID 7547305, doi 10.1099/00207713-45-4-820","examAdvice":"ในข้อสอบให้ตอบปี 1995 ตามที่สอน แล้วจำไว้ว่างานเพาะเลี้ยงตีพิมพ์ปี 1993 ส่วนปี 1995 คือปีที่ตั้งชื่อเชื้อ","sourceRef":"PMID 8501214 (doi 10.1128/jcm.31.5.1136-1142.1993) และ PMID 7547305 (doi 10.1099/00207713-45-4-820)"}],"swine-clinic--swine-ileitis-bacti--proliferative-enteropathy-การวินิจฉัย":[{"severity":"narrows","lectureSays":"โน้ตเขียนว่า fecal PCR มี specificity สูงมาก 100% และ sensitivity 39-72% และจัด PCR of feces ให้แม่นกว่า immunoassay of feces","evidenceSays":"บทความทบทวนอย่างเป็นระบบ Diagnostic performance of different fecal Lawsonia intracellularis-specific polymerase chain reaction assays as diagnostic tests for proliferative enteropathy in pigs: a review, PMID 20622217, doi 10.1177/104063871002200401 คำนวณจากงานที่ตีพิมพ์ได้ sensitivity 36-100% และ specificity 50-100% แล้วแต่ assay และชี้ว่า fecal PCR มีแนวโน้มประเมินจำนวนสุกรที่มีรอยโรคสูงเกินจริงมากกว่าต่ำเกินจริง ส่วนงาน Comparison of different methods for diagnosis of porcine proliferative enteropathy, PMID 11989741 (สุกร 40 ตัวที่ให้เชื้อ) พบว่า immunoperoxidase stain ของ fecal smear ไวกว่า PCR ในการตรวจการขับเชื้อ คือ 89.5% เทียบกับ 60.5% ที่วันที่ 21 และ 59.4% เทียบกับ 37.5% ที่วันที่ 28","examAdvice":"ในข้อสอบให้ตอบ specificity 100% และ sensitivity 39-72% ตามสไลด์ แต่เวลาแปลผล fecal PCR จริงอย่าถือว่าผลบวกแปลว่ามีรอยโรคเสมอ ให้ดูอาการ serology และ histology ร่วมด้วย","sourceRef":"PMID 20622217 (doi 10.1177/104063871002200401) และ PMID 11989741"}],"swine-clinic--swine-ileitis-bacti--yersinia-infection":[{"severity":"narrows","lectureSays":"โน้ตเขียนว่า Yersinia พบไม่บ่อยในสุกร ประเด็นหลักคือเป็น zoonosis","evidenceSays":"สิ่งที่พบไม่บ่อยคืออาการป่วยในสุกร ไม่ใช่ตัวเชื้อ บทความทบทวน Zoonotic Yersinia enterocolitica in Swine: One Health Implications for Food Safety and Public Health, PMID 41012721, doi 10.3390/vetsci12090795 ระบุว่าสุกรเป็น reservoir หลักของ Y. enterocolitica พบเชื้อบ่อยที่ tonsil และลำไส้ และเชื้อปนเปื้อนเนื้อได้ระหว่างการฆ่า โดย bioserotype 4/O:3 เป็นสาเหตุของโรคในคนบ่อยที่สุด บทความ Unique virulence properties of Yersinia enterocolitica O:3: an emerging zoonotic pathogen using pigs as preferred reservoir host, PMID 25172222, doi 10.1016/j.ijmm.2014.07.008 ระบุเช่นกันว่าสุกรเป็น reservoir หลักของ 4/O:3 และมักเป็น carrier ที่ไม่แสดงอาการ","examAdvice":"ในข้อสอบให้ตอบว่าพบไม่บ่อยในสุกรตามสไลด์ แต่เวลาทำงานด้าน food safety จริงให้ถือว่าสุกรที่ดูปกติเป็นแหล่งเชื้อหลักของ Y. enterocolitica โดยเฉพาะที่ tonsil","sourceRef":"PMID 41012721 (doi 10.3390/vetsci12090795) และ PMID 25172222 (doi 10.1016/j.ijmm.2014.07.008)"}],"swine-clinic--swine-repro--porcine-brucellosis-brucella-suis":[{"severity":"contradicts","lectureSays":"โน้ตใส่ vaccination ไว้ทั้งในหัวข้อ control และ prevention ของ porcine brucellosis","evidenceSays":"บทความทบทวน Swine brucellosis: current perspectives, PMID 30050849, doi 10.2147/VMRR.S91360 ระบุว่ายังไม่มีวัคซีนเชิงพาณิชย์ที่ได้รับอนุมัติสำหรับป้องกัน brucellosis ในสุกร และการ depopulation ทั้งฝูงเป็นมาตรการควบคุมที่ได้ผลที่สุด WOAH Terrestrial Manual 2022 บทที่ 3.1.4 Brucellosis ข้อ 1.1.4 ระบุว่ามีความพยายามพัฒนาวัคซีนสำหรับ B. suis ในสุกร แต่ยังไม่มีตัวใดได้ผลเต็มที่ วัคซีนเชื้อเป็น B. suis strain 2 (S2) ที่ผลิตในจีนใช้กันแพร่หลายในประเทศนั้น แต่ยังไม่มีข้อมูลประสิทธิภาพต่อ B. suis จากการทดลองที่ควบคุมเข้มงวด และบทสรุปของบทเดียวกันเขียนว่ายังไม่มีวัคซีนที่เหมาะสำหรับควบคุม Brucella ในสุกร ส่วน MSD Veterinary Manual หัวข้อ Abortion in Pigs (ปรับปรุง Sept 2026) ให้การควบคุมอาศัย test-and-cull","examAdvice":"ในข้อสอบให้ตอบ vaccination ตามสไลด์ แต่เวลาวางแผนควบคุมโรคในฟาร์มจริงให้ใช้การตรวจ serology แล้วคัดทิ้งกับฝูงปิดเป็นหลัก เพราะยังไม่มีวัคซีนสุกรที่ได้ผลเต็มที่","sourceRef":"PMID 30050849 (doi 10.2147/VMRR.S91360) และ WOAH Terrestrial Manual 2022, Chapter 3.1.4 Brucellosis, Section 1.1.4"}],"swine-clinic--swine-repro--porcine-parvovirus-ppv":[{"severity":"narrows","lectureSays":"รายการอาการของ PPV ในโน้ตมี abortion รวมอยู่ด้วย ขณะที่หัวข้อการวินิจฉัยของโน้ตเองเขียนว่าแม่ไม่แท้ง","evidenceSays":"บทความ The effect of porcine parvovirus and porcine reproductive and respiratory syndrome virus on porcine reproductive performance, PMID 10844195, doi 10.1016/s0378-4320(00)00135-4 บรรยายว่าการระบาดของ PPV แสดงออกเป็น mummified fetus จำนวนมากขึ้น ถ้าติดเชื้อช่วงต้นของการตั้งท้องจำนวนลูกเกิดมีชีวิตจะลดลงจาก embryonic death กับ resorption แม่แทบไม่แสดงอาการ และ PPV ไม่น่าเป็นสาเหตุโดยตรงของการแท้ง ต่างจาก PRRSV ที่ทำให้แท้ง ลูกตายช่วงท้าย stillborn และลูกอ่อนแอ MSD Veterinary Manual หัวข้อ Abortion in Pigs (ปรับปรุง Sept 2026) ให้ลักษณะเด่นของ PPV เป็นครอกที่มีลูกตายหลายขนาดรวมทั้ง mummified fetus ปนกับ stillborn และลูกปกติในสุกรสาวท้องแรก","examAdvice":"ในข้อสอบให้ตอบรายการอาการตามสไลด์ แต่เวลาแยกโรคจริง ฝูงที่แท้งเป็นหลักให้นึกถึง PRRSV หรือสาเหตุอื่นก่อน ส่วน PPV เด่นที่ลูกมัมมี่หลายขนาดโดยแม่ไม่แท้ง","sourceRef":"PMID 10844195 (doi 10.1016/s0378-4320(00)00135-4)"}],"swine-clinic--swine-trichinosis--ทริคิโนซิส-การวินิจฉัย-การรักษา-และการควบคุม":[{"severity":"narrows","lectureSays":"โน้ตเขียนว่าในคนให้ thiabendazole 50 mg/kg กินวันละ 2 ครั้ง 5-10 วัน","evidenceSays":"thiabendazole ใช้ได้ผลจริง แต่แนวทางปัจจุบันไม่ได้ใช้เป็นยาแรก หน้า Clinical Care of Trichinellosis ของ US CDC (12 March 2024) ให้ยาที่แนะนำเป็น albendazole 400 mg วันละ 2 ครั้ง 8-14 วัน หรือ mebendazole 200-400 mg วันละ 3 ครั้ง 3 วัน แล้วต่อด้วย 400-500 mg วันละ 3 ครั้งอีก 10 วัน บทความ Opinion on the diagnosis and treatment of human trichinellosis, PMID 12150691, doi 10.1517/14656566.3.8.1117 ให้ mebendazole หรือ albendazole ร่วมกับ glucocorticosteroid เช่นกัน ส่วน thiabendazole ที่เคยทดลองในไทย งาน Blinded, placebo-controlled trial of antiparasitic drugs for trichinosis myositis, PMID 10882628, doi 10.1086/315645 (ผู้ป่วย 46 คนที่เชียงราย) ใช้ 25 mg/kg วันละ 2 ครั้ง 10 วัน คือรวม 50 mg/kg ต่อวัน ผู้ป่วยที่ได้ thiabendazole ดีขึ้นทั้ง 7 ราย แต่อาสาสมัคร 30% ทนผลข้างเคียงไม่ได้ ตัวเลข 50 mg/kg ในโน้ตจึงควรอ่านเป็นขนาดรวมต่อวันที่แบ่งให้ 2 ครั้ง ไม่ใช่ 50 mg/kg ต่อครั้ง","examAdvice":"ในข้อสอบให้ตอบ thiabendazole 50 mg/kg วันละ 2 ครั้ง 5-10 วันตามสไลด์ แต่เวลาให้ข้อมูลหรือส่งต่อผู้ป่วยจริงให้อ้าง albendazole หรือ mebendazole ตามแนวทางปัจจุบัน และถ้าต้องใช้ thiabendazole ให้คิดเป็น 25 mg/kg ต่อครั้ง วันละ 2 ครั้ง","sourceRef":"US CDC, Clinical Care of Trichinellosis (12 March 2024) และ PMID 10882628 (doi 10.1086/315645)"}]};
